public final class NativeItemsSmokeTest {
    private static int checks;
    private static void check(boolean ok,String text){checks++;if(!ok)throw new AssertionError(text);}
    private static void same(Object a,Object b,String text){check(Objects.equals(a,b),text+": "+a+" != "+b);}
    private static void rejects(Runnable work,String text){try{work.run();throw new AssertionError(text);}catch(IllegalArgumentException|IllegalStateException expected){check(true,text);}}
    private static PlayerStateV5 state(String name,int agility){return PlayerCreationV5.create(name,0,Job.WIZARD,0,20,agility,20,100,10);}
    private static Monster enemy(int hp){return EncounterFactory.buildMonster("Item foe",hp,1,40);}
    private static CombatRoundV5 round(List<PlayerRuntimeV5> party,Monster enemy,ToIntFunction<Object> initiative,boolean hit,Predicate<PlayerRuntimeV5> escape){return new CombatRoundV5(party,List.of(enemy),Map.of(),Map.of(),initiative,(p,m)->true,(m,p)->hit,m->10,(p,m)->true,(p,m)->true,escape);}
    private static CombatRoundV5 round(List<PlayerRuntimeV5> party,Monster enemy){return round(party,enemy,a->a instanceof PlayerRuntimeV5 p?p.attribute(PlayerStateV5.Attribute.AGILITY):10,false,p->false);}
    private static long used(RoundResult result){return result.events().stream().filter(e->e instanceof CombatEvent.ItemUsed).count();}
    public static void main(String[] args)throws Exception{
        if(args.length>0){var app=new DiagnosticApplication(DiagnosticContent.load(Path.of(args[1])),()->{});app.loadNative(Path.of(args[2]));same(0,app.nativeCampaign().party().get(0).getInventoryItemId(9),"child consumed potion absent");same(102,app.nativeCampaign().party().get(0).getInventoryItemId(0),"child unused potion retained");same(10,app.nativeCampaign().party().get(1).runtime().mp(),"child recovered MP retained");System.out.println("NATIVE_ITEMS_CHILD PASS");return;}
        restoration();contracts();changedBattlefield();campaign();screens();System.out.println("NATIVE_ITEMS checks="+checks+" PASS");
    }
    private static void restoration(){
        var as=state("User",20);as.setInventory(9,102);as.setExperience(123);as.setEquipment(com.phantasia.core.model.item.EquipSlot.WEAPON,61);var a=new PlayerRuntimeV5(as);var b=new PlayerRuntimeV5(state("Ally",18));a.damage(20);b.damage(2);var foe=enemy(100);var combat=round(List.of(a,b),foe);var plan=CombatRoundV5.PlayerOrder.item(a,9,b);
        same(102,plan.itemUse().itemId(),"order captures exact item ID");same(9,plan.itemUse().slot(),"order captures tenth slot");same(102,a.inventoryItemId(9),"planning never consumes potion");same(98,b.hp(),"planning never heals");var result=combat.runRound(List.of(plan,CombatRoundV5.PlayerOrder.parry(b)));same(100,b.hp(),"HP potion clamps at target maximum");same(80,a.hp(),"explicit ally selection does not heal user");same(0,a.inventoryItemId(9),"potion consumed once at resolution");same(1L,used(result),"one item event");var event=(CombatEvent.ItemUsed)result.events().stream().filter(e->e instanceof CombatEvent.ItemUsed).findFirst().orElseThrow();same(2,event.amount(),"event reports actual HP restored");check(!event.magic(),"HP resource in event");same(102,event.itemId(),"event preserves item provenance");check(new CombatNarrator().narrateRound(result).stream().anyMatch(s->s.contains("restores 2 HP")),"narrator uses item restoration event");same(123L,a.experience(),"inventory consumption cannot corrupt XP");same(61,a.equippedItemId(com.phantasia.core.model.item.EquipSlot.WEAPON),"inventory consumption cannot corrupt equipment");same(10,a.mp(),"item has no MP cost");same(100,foe.getHp(),"item action does not also attack");
        var ms=state("Mana user",20);ms.setInventory(0,111);var mana=new PlayerRuntimeV5(ms);mana.spendMp(2);var mp=round(List.of(mana),enemy(100)).runRound(List.of(CombatRoundV5.PlayerOrder.item(mana,0,mana)));same(10,mana.mp(),"magic potion restores MP with clamp");same(0,mana.inventoryItemId(0),"magic potion consumed");var me=(CombatEvent.ItemUsed)mp.events().stream().filter(e->e instanceof CombatEvent.ItemUsed).findFirst().orElseThrow();same(2,me.amount(),"actual MP event amount");check(me.magic(),"MP event resource");
    }
    private static void contracts(){
        var as=state("User",20);as.setInventory(0,102);as.setInventory(1,61);as.setInventory(2,121);var a=new PlayerRuntimeV5(as);var b=new PlayerRuntimeV5(state("Ally",18));var outsider=new PlayerRuntimeV5(state("Other",15));var foe=enemy(100);var combat=round(List.of(a,b),foe);
        rejects(()->CombatRoundV5.PlayerOrder.item(a,-1,b),"negative slot rejected");rejects(()->CombatRoundV5.PlayerOrder.item(a,10,b),"slot outside native pack rejected");rejects(()->CombatRoundV5.PlayerOrder.item(a,3,b),"empty slot rejected");rejects(()->CombatRoundV5.PlayerOrder.item(a,1,b),"equipment is not a potion");rejects(()->CombatRoundV5.PlayerOrder.item(a,2,b),"scroll is not consumed in combat");rejects(()->new CombatRoundV5.PlayerOrder(a,Action.USE_ITEM,null,null,null,null),"item action needs payload and ally");rejects(()->new CombatRoundV5.PlayerOrder(a,Action.ATTACK,foe,null,null,CombatRank.FRONT,new CombatRoundV5.ItemUse(0,102)),"non-item action cannot carry item payload");
        rejects(()->combat.runRound(List.of(CombatRoundV5.PlayerOrder.item(a,0,b))),"full HP target rejected before round");b.damage(20);outsider.damage(10);rejects(()->combat.runRound(List.of(CombatRoundV5.PlayerOrder.item(a,0,outsider))),"foreign ally rejected");rejects(()->combat.runRound(List.of(CombatRoundV5.PlayerOrder.item(a,0,b),CombatRoundV5.PlayerOrder.attack(a,foe,CombatRank.FRONT))),"item cannot be a second action");same(102,a.inventoryItemId(0),"invalid plan retains potion");same(80,b.hp(),"invalid plan does not heal");same(100,foe.getHp(),"invalid plan cannot damage enemy");
        var selected=CombatRoundV5.PlayerOrder.item(a,0,b);as.setInventory(0,103);rejects(()->combat.runRound(List.of(selected)),"changed source slot must be reviewed before confirmation");same(103,a.inventoryItemId(0),"replacement potion not consumed by stale plan");var valid=combat.runRound(List.of(CombatRoundV5.PlayerOrder.item(a,0,b)));same(1,valid.roundNumber(),"invalid plans never advance round");same(89,b.hp(),"fresh selection uses new potion definition");
        b.damage(100);as.setInventory(0,102);rejects(()->combat.runRound(List.of(CombatRoundV5.PlayerOrder.item(a,0,b))),"dead target rejected; potion cannot resurrect");same(102,a.inventoryItemId(0),"dead-target failure preserves item");
    }
    private static void changedBattlefield(){
        var as=state("First",20);var bs=state("Second",18);as.setInventory(0,102);bs.setInventory(0,102);var a=new PlayerRuntimeV5(as);var b=new PlayerRuntimeV5(bs);b.damage(2);var result=round(List.of(a,b),enemy(100)).runRound(List.of(CombatRoundV5.PlayerOrder.item(a,0,b),CombatRoundV5.PlayerOrder.item(b,0,b)));same(1L,used(result),"earlier heal makes later potion unnecessary");same(0,a.inventoryItemId(0),"first useful potion consumed");same(102,b.inventoryItemId(0),"later now-unneeded potion retained");check(result.events().stream().anyMatch(e->e instanceof CombatEvent.ActionSkipped),"changed target emits explicit skip");
        var ts=state("Target",5);var us=state("User",20);ts.setHp(5);us.setInventory(0,102);var target=new PlayerRuntimeV5(ts);var user=new PlayerRuntimeV5(us);var killed=round(List.of(target,user),enemy(100),p->p instanceof PlayerRuntimeV5 v?v.attribute(PlayerStateV5.Attribute.AGILITY):30,true,p->false).runRound(List.of(CombatRoundV5.PlayerOrder.parry(target),CombatRoundV5.PlayerOrder.item(user,0,target)));same(0,target.hp(),"faster enemy kills target before potion");same(102,user.inventoryItemId(0),"dead-at-resolution target keeps potion");same(0L,used(killed),"no potion event or resurrection after target death");
        var ds=state("Doomed",20);ds.setHp(5);ds.setInventory(0,102);var doomed=new PlayerRuntimeV5(ds);var ally=new PlayerRuntimeV5(state("Survivor",18));ally.damage(10);var deadUser=round(List.of(doomed,ally),enemy(100),p->p instanceof PlayerRuntimeV5 v?v.attribute(PlayerStateV5.Attribute.AGILITY):30,true,p->false).runRound(List.of(CombatRoundV5.PlayerOrder.item(doomed,0,ally),CombatRoundV5.PlayerOrder.parry(ally)));same(0,doomed.hp(),"user dies before turn");same(102,doomed.inventoryItemId(0),"dead user cannot consume");same(90,ally.hp(),"dead user's target not healed");same(0L,used(deadUser),"dead user's item not executed");
        var ss=state("Sleeper",20);ss.setInventory(0,102);var sleeper=new PlayerRuntimeV5(ss);sleeper.setAsleep(true);var asleep=round(List.of(sleeper,ally),enemy(100)).runRound(List.of(CombatRoundV5.PlayerOrder.item(sleeper,0,ally),CombatRoundV5.PlayerOrder.parry(ally)));same(102,sleeper.inventoryItemId(0),"sleeping user retains item");same(0L,used(asleep),"sleeping user cannot use potion");
        var cs=state("Changed",20);cs.setInventory(0,102);var changing=new PlayerRuntimeV5(cs);var adjusted=round(List.of(changing,ally),enemy(100),p->{if(p==changing)cs.setInventory(0,103);return p instanceof PlayerRuntimeV5?20:10;},false,p->false).runRound(List.of(CombatRoundV5.PlayerOrder.item(changing,0,ally),CombatRoundV5.PlayerOrder.parry(ally)));same(103,changing.inventoryItemId(0),"source replacement after validation is not substituted");same(0L,used(adjusted),"source change skips resolution");
        var rs=state("Runner",30);var ps=state("Potion user",20);ps.setInventory(0,102);var runner=new PlayerRuntimeV5(rs);var potionUser=new PlayerRuntimeV5(ps);runner.damage(10);var retreat=round(List.of(runner,potionUser),enemy(100),p->p instanceof PlayerRuntimeV5 v?v.attribute(PlayerStateV5.Attribute.AGILITY):10,false,p->true).runRound(List.of(CombatRoundV5.PlayerOrder.run(runner),CombatRoundV5.PlayerOrder.item(potionUser,0,runner)));same(CombatOutcome.ESCAPED,retreat.outcome(),"escape ends before later item");same(102,potionUser.inventoryItemId(0),"escape preserves unexecuted potion");same(90,runner.hp(),"escape does not apply unexecuted healing");
        var killer=new PlayerRuntimeV5(state("Killer",30));var victim=enemy(1);var won=round(List.of(killer,potionUser),victim).runRound(List.of(CombatRoundV5.PlayerOrder.attack(killer,victim,CombatRank.FRONT),CombatRoundV5.PlayerOrder.item(potionUser,0,runnerInParty(potionUser))));
        same(CombatOutcome.VICTORY,won.outcome(),"victory stops later item");same(102,potionUser.inventoryItemId(0),"victory preserves unexecuted potion");
    }
    private static PlayerRuntimeV5 runnerInParty(PlayerRuntimeV5 player){player.damage(1);return player;}
    private static void campaign(){
        var c=NativeProgressionScreen.freshCampaign();var a=c.party().get(0);var b=c.party().get(1);a.setInventoryItem(0,102);a.setInventoryItem(9,111);b.runtime().damage(10);b.runtime().spendMp(3);var battle=c.startBattle(List.of(enemy(100)),ignored->10,p->false);same(List.of(0,9),battle.potionSlots(a),"all ten carried slots are visible to planner");same(List.of(b),battle.potionTargets(a,0),"only beneficial living allies offered");battle.selectPotion(a,0,null);same(b.runtime(),battle.rows().get(0).order().allyTarget(),"automatic potion target uses party order");same(102,a.getInventoryItemId(0),"native selection does not consume");battle.select(b,Action.PARRY,null);check(battle.canConfirm(),"item is ordinary single member order");a.setInventoryItem(0,103);check(!battle.canConfirm(),"changed potion marks plan for review");same(CombatOrderPlannerV5.RowStatus.NEEDS_REVIEW,battle.rows().get(0).status(),"stale item row review status");rejects(battle::confirmRound,"stale item cannot run full plan");
        var other=NativeProgressionScreen.freshCampaign().party().get(0);rejects(()->battle.selectPotion(a,9,other),"foreign potion recipient rejected");rejects(()->battle.select(a,Action.USE_ITEM,null),"generic action cannot bypass item selection");battle.selectPotion(a,9,null);same(b.runtime(),battle.rows().get(0).order().allyTarget(),"automatic MP target skips full MP allies");battle.confirmRound();same(10,b.runtime().mp(),"native campaign item restores same battle runtime");same(0,a.getInventoryItemId(9),"native item consumes exact slot");check(a.learned().isEmpty()&&a.readied().isEmpty(),"item needs no learned or readied technique");
    }
    private static void key(ScreenManager manager,int code){var canvas=new Canvas();manager.getActiveScreen().onKeyPressed(new KeyEvent(canvas,KeyEvent.KEY_PRESSED,0,0,code,KeyEvent.CHAR_UNDEFINED));manager.update(.2f);manager.update(.2f);manager.getActiveScreen().onKeyReleased(new KeyEvent(canvas,KeyEvent.KEY_RELEASED,0,0,code,KeyEvent.CHAR_UNDEFINED));}
    private static void render(ScreenManager manager,String name)throws Exception{var image=new BufferedImage(GameCanvas.DESIGN_WIDTH,GameCanvas.DESIGN_HEIGHT,BufferedImage.TYPE_INT_RGB);var g=image.createGraphics();try{manager.render(g,image.getWidth(),image.getHeight());}finally{g.dispose();}check(image.getRGB(80,80)!=0xff000000,"item screen renders "+name);javax.imageio.ImageIO.write(image,"png",Path.of(System.getProperty("java.io.tmpdir"),"native-items-"+name+".png").toFile());}
    private static void screens()throws Exception{
        Path root=Files.createTempDirectory("native-items-save-");try{var content=DiagnosticContent.exportAndLoad(DiagnosticContent.create(),root.resolve("content"));var c=NativeProgressionScreen.freshCampaign();var a=c.party().get(0);var b=c.party().get(1);a.setInventoryItem(0,102);a.setInventoryItem(9,111);a.runtime().damage(10);b.runtime().damage(10);b.runtime().spendMp(3);
            var t=new LocalMapTraversal(content.maps(),c,DiagnosticContent.DUNGEON,null);var flow=new NativeLocalEncounterFlow(t,c,()->List.of(enemy(100)),ignored->10,p->true);var visit=new LocalMapScreen.Visit(t,GameState.WORLD_ROAM,null,flow);var manager=new ScreenManager();manager.register(GameState.NATIVE_LOCAL_MAP,new LocalMapScreen(manager,c,content.npcs(),content.shops(),()->List.of(enemy(100))));manager.register(GameState.NATIVE_DIAGNOSTIC,new NativeProgressionScreen(manager,c));manager.switchTo(GameState.NATIVE_LOCAL_MAP,visit);for(int i=0;i<6;i++)key(manager,KeyEvent.VK_RIGHT);var battle=c.activeBattle();key(manager,KeyEvent.VK_I);same(Action.USE_ITEM,battle.rows().get(0).order().action(),"I selects actual carried potion");same(a.runtime(),battle.rows().get(0).order().allyTarget(),"automatic HP target first injured ally");key(manager,KeyEvent.VK_Y);same(b.runtime(),battle.rows().get(0).order().allyTarget(),"Y overrides potion ally");same(102,a.getInventoryItemId(0),"UI targeting does not consume");key(manager,KeyEvent.VK_I);same(9,battle.rows().get(0).order().itemUse().slot(),"I cycles to tenth-slot magic potion");same(b.runtime(),battle.rows().get(0).order().allyTarget(),"UI automatic mana recipient");render(manager,"plan");key(manager,KeyEvent.VK_DOWN);key(manager,KeyEvent.VK_D);key(manager,KeyEvent.VK_UP);key(manager,KeyEvent.VK_ENTER);same(0,a.getInventoryItemId(9),"UI resolution consumes potion");same(10,b.runtime().mp(),"UI restores same native MP");same(CombatOrderPlannerV5.RowStatus.NEEDS_ORDER,battle.rows().get(0).status(),"item order cleared for next review");check(!battle.canConfirm(),"no automatic repeat item command");int hp=a.runtime().hp();key(manager,KeyEvent.VK_ENTER);same(hp,a.runtime().hp(),"missing next order cannot run another enemy turn");render(manager,"result");key(manager,KeyEvent.VK_I);key(manager,KeyEvent.VK_D);same(102,a.getInventoryItemId(0),"changing away from potion retains it");key(manager,KeyEvent.VK_F);key(manager,KeyEvent.VK_ENTER);same(CombatOutcome.ESCAPED,battle.outcome(),"escape replaces pending item as sole action");same(102,a.getInventoryItemId(0),"replaced item retained after escape");key(manager,KeyEvent.VK_ENTER);same(GameState.NATIVE_LOCAL_MAP,manager.getActiveState(),"item battle returns to same native visit");
            String id=AuthoredContentFingerprint.compute(content.maps(),content.npcs(),content.shops());var save=root.resolve("items.pns");NativeSaveManager.save(save,new NativeSaveManager.Checkpoint(id,c.snapshot(),t.snapshot(),flow.snapshot()),id,content.maps(),content.shops(),p->p.equals(new WorldPosition(0,0)));var fresh=new DiagnosticApplication(DiagnosticContent.load(root.resolve("content")),()->{});fresh.loadNative(save);same(0,fresh.nativeCampaign().party().get(0).getInventoryItemId(9),"consumption persists through checkpoint");same(102,fresh.nativeCampaign().party().get(0).getInventoryItemId(0),"unconsumed potion persists");same(10,fresh.nativeCampaign().party().get(1).runtime().mp(),"restored MP persists");
            var child=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin/java").toString(),"--enable-preview","-Djava.awt.headless=true","-cp",System.getProperty("java.class.path"),NativeItemsSmokeTest.class.getName(),"--child",root.resolve("content").toString(),save.toString()).redirectErrorStream(true).start();check(child.waitFor(30,java.util.concurrent.TimeUnit.SECONDS),"item restart child completes");var output=new String(child.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);check(child.exitValue()==0&&output.contains("NATIVE_ITEMS_CHILD PASS"),"fresh process preserves item results: "+output);
        }finally{try(var files=Files.walk(root)){for(var p:files.sorted(Comparator.reverseOrder()).toList())Files.delete(p);}}
    }
}
